import bisect

def solve(nums):
    """Return length of longest strictly increasing subsequence in list nums."""
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # find position to insert x in tails to keep tails increasing
        # for strictly increasing, we use bisect_left on tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

