def solve(n, b):
    if b < 2 or b > 36:
        raise ValueError('Base out of range')
    if n == 0:
        return '0'
    sign = '-' if n < 0 else ''
    num = -n if n < 0 else n
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    res = []
    while num:
        res.append(digits[num % b])
        num //= b
    return sign + ''.join(reversed(res))

