def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    - Resolve '.' (current directory) and '..' (parent directory).
    - Collapse multiple consecutive slashes.
    - Remove trailing slash unless the result is root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

