import heapq

def solve(n, edges):
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
