    start = 0
    for i, ch in enumerate(iterator):
        prev = seen.get(ch)
        if prev is not None and prev >= start:
            start = prev + 1
        seen[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

