def solve(tokens):
    """Evaluate Reverse Polish Notation expression, same semantics as T06.
    Tokens are strings representing integers or operators + - * /.
    Division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

