    # Split the path by '/' and process each component.
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            # empty part (due to leading, trailing, or //) or current dir: ignore
            continue
        if part == '..':
            # go up one directory if possible
            if stack:
                stack.pop()
        else:
            # regular directory name
            stack.append(part)
    # Reconstruct the simplified path
    return '/' + '/'.join(stack)

