def solve(matrix):
    """Return determinant of integer matrix using Bareiss algorithm (exact integer arithmetic).
    An empty matrix (size 0) has determinant 1 per spec.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Make a deep copy to avoid mutating input
    A = [row[:] for row in matrix]
    # Bareiss algorithm
    det = 1
    for k in range(n - 1):
        # Find pivot; if zero, try to swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det  # Swapping rows flips sign
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Update entry using integer division
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // (A[k - 1][k - 1] if k > 0 else 1)
        # Zero out column below pivot
        for i in range(k + 1, n):
            A[i][k] = 0
    return det * A[n - 1][n - 1]

