def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Sliding window implementation.
    """
    last_idx = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            start = last_idx[ch] + 1
        last_idx[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

