def solve(coins, amount):
    # DP for min coins, unlimited usage. Return -1 if impossible.
    # Use large sentinel for unreachable.
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != max_val else -1

